-- G2 state store on PostgreSQL (generated by dashboard/pg_backend.py; do not edit by hand).
-- One store per schema: CREATE SCHEMA <name>; SET search_path TO <name>; then this file.
-- Mirrors dashboard/state_store.py (SQLite): same tables, CHECKs, guard triggers and messages.
CREATE TABLE IF NOT EXISTS store_meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS action_plan (
  action_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id      BIGINT,
  stay_date       TEXT,
  room_type       TEXT,
  action_type     TEXT NOT NULL CONSTRAINT action_type_known CHECK (action_type IN ('confirm_email','reminder','phone_call','offer_change','request_deposit','price_adjustment','capacity_allocation','resale','overbooking')),
  rule_id         TEXT NOT NULL,
  source_run_id   TEXT,
  decision_at     TEXT NOT NULL,
  known_from      TEXT,
  scheduled_at    TEXT,
  arrival_date    TEXT,
  message_no      INTEGER,
  note            TEXT,
  basis_event_id  BIGINT,
  needs_approval  INTEGER NOT NULL CHECK (needs_approval IN (0,1)),
  approval_status TEXT NOT NULL CHECK (approval_status IN ('auto','pending','approved','rejected')),
  approved_by     TEXT,
  approved_at     TEXT,
  created_at      TEXT NOT NULL,
  CONSTRAINT approval_needed_not_auto CHECK (needs_approval = 0 OR approval_status <> 'auto'),
  CONSTRAINT decision_recorded CHECK ((approval_status IN ('approved','rejected') AND approved_by IS NOT NULL
          AND approved_at IS NOT NULL) OR
         (approval_status IN ('auto','pending') AND approved_by IS NULL AND approved_at IS NULL)),
  CONSTRAINT approved_after_created CHECK (approved_at IS NULL OR approved_at >= created_at),
  CONSTRAINT scheduled_after_decision CHECK (scheduled_at IS NULL OR scheduled_at >= decision_at),
  CONSTRAINT decided_before_arrival CHECK (arrival_date IS NULL OR decision_at < arrival_date),
  CONSTRAINT sensitive_needs_approval CHECK (action_type NOT IN ('capacity_allocation','offer_change','overbooking','price_adjustment','request_deposit','resale') OR needs_approval = 1),
  CONSTRAINT booking_action_has_booking CHECK (action_type NOT IN ('confirm_email','reminder','phone_call','offer_change','request_deposit') OR booking_id IS NOT NULL),
  CONSTRAINT date_action_has_cell CHECK (action_type NOT IN ('price_adjustment','capacity_allocation','resale','overbooking')
         OR (stay_date IS NOT NULL AND room_type IS NOT NULL)),
  CONSTRAINT deposit_has_policy CHECK (action_type <> 'request_deposit' OR (note IS NOT NULL AND trim(note) <> '')),
  CONSTRAINT offer_has_basis CHECK (action_type <> 'offer_change' OR basis_event_id IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_action_schedule
  ON action_plan (booking_id, action_type, scheduled_at) WHERE scheduled_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS interventions (
  intervention_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action_id       BIGINT NOT NULL UNIQUE REFERENCES action_plan(action_id),
  channel         TEXT NOT NULL CHECK (channel IN ('task','email','sms','phone','pms')),
  as_of           TEXT NOT NULL,
  executed_at     TEXT NOT NULL,
  executed_by     TEXT NOT NULL CHECK (executed_by IN ('staff','n8n')),
  outcome         TEXT NOT NULL CHECK (outcome IN ('no_response','confirmed','requested_change','cancelled','completed')),
  cost            DOUBLE PRECISION,
  precheck        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS guest_responses (
  response_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id    BIGINT NOT NULL,
  action_id     BIGINT NOT NULL REFERENCES action_plan(action_id),
  response      TEXT NOT NULL CHECK (response IN ('confirmed','requested_change','cancelled')),
  response_at   TEXT NOT NULL,
  recorded_at   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS response_events (
  event_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  intervention_id BIGINT UNIQUE REFERENCES interventions(intervention_id),
  response_id     BIGINT UNIQUE REFERENCES guest_responses(response_id),
  CHECK ((intervention_id IS NOT NULL) <> (response_id IS NOT NULL))
);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_namespace n ON n.oid = c.connamespace
                 WHERE c.conname = 'action_plan_basis_fk' AND n.nspname = current_schema()) THEN
    ALTER TABLE action_plan ADD CONSTRAINT action_plan_basis_fk
      FOREIGN KEY (basis_event_id) REFERENCES response_events(event_id);
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS action_closures (
  closure_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action_id   BIGINT NOT NULL UNIQUE REFERENCES action_plan(action_id),
  reason      TEXT NOT NULL CHECK (trim(reason) <> ''),
  closed_by   TEXT NOT NULL CHECK (trim(closed_by) <> ''),
  as_of       TEXT NOT NULL,
  closed_at   TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS plan_reviews (
  review_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id  BIGINT NOT NULL UNIQUE,
  rule_id     TEXT NOT NULL CHECK (rule_id IN ('I1','I2','I3')),
  decision    TEXT NOT NULL CHECK (decision IN ('approved','rejected')),
  reviewer    TEXT NOT NULL CHECK (trim(reviewer) <> ''),
  reason      TEXT,
  batch_id    TEXT,
  as_of       TEXT NOT NULL,
  reviewed_at TEXT NOT NULL,
  CONSTRAINT rejection_has_reason CHECK (decision <> 'rejected' OR (reason IS NOT NULL AND trim(reason) <> ''))
);

CREATE TABLE IF NOT EXISTS execution_attempts (
  attempt_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action_id       BIGINT NOT NULL REFERENCES action_plan(action_id),
  executor        TEXT NOT NULL CHECK (executor IN ('n8n')),
  result          TEXT NOT NULL CHECK (result IN ('accepted','refused','error')),
  detail          TEXT,
  intervention_id BIGINT UNIQUE REFERENCES interventions(intervention_id),
  as_of           TEXT NOT NULL,
  attempted_at    TEXT NOT NULL,
  CONSTRAINT accepted_has_execution CHECK ((result = 'accepted') = (intervention_id IS NOT NULL))
);

-- Shared event order across contact outcomes and late responses (same transaction).
CREATE OR REPLACE FUNCTION sequence_intervention() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN INSERT INTO response_events (intervention_id) VALUES (NEW.intervention_id); RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER sequence_intervention AFTER INSERT ON interventions
  FOR EACH ROW EXECUTE FUNCTION sequence_intervention();
CREATE OR REPLACE FUNCTION sequence_response() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN INSERT INTO response_events (response_id) VALUES (NEW.response_id); RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER sequence_response AFTER INSERT ON guest_responses
  FOR EACH ROW EXECUTE FUNCTION sequence_response();

CREATE OR REPLACE FUNCTION guard_interventions() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF NOT EXISTS (SELECT 1 FROM action_plan a WHERE a.action_id = NEW.action_id AND (a.approval_status = 'approved' OR (a.approval_status = 'auto' AND a.needs_approval = 0))) THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Blocked: action lacks required approval'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_interventions BEFORE INSERT ON interventions FOR EACH ROW EXECUTE FUNCTION guard_interventions();


CREATE OR REPLACE FUNCTION guard_interventions_closed() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  PERFORM 1 FROM action_plan WHERE action_id = NEW.action_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM action_closures WHERE action_id = NEW.action_id) THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Blocked: action was closed without contact'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_interventions_closed BEFORE INSERT ON interventions FOR EACH ROW EXECUTE FUNCTION guard_interventions_closed();


CREATE OR REPLACE FUNCTION guard_g3_disabled() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF NEW.action_type = 'overbooking' THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'G3 overbooking is disabled by policy'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_g3_disabled BEFORE INSERT ON action_plan FOR EACH ROW EXECUTE FUNCTION guard_g3_disabled();


CREATE OR REPLACE FUNCTION guard_interventions_g3() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF EXISTS (SELECT 1 FROM action_plan WHERE action_id = NEW.action_id AND action_type = 'overbooking') THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'G3 overbooking is disabled by policy'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_interventions_g3 BEFORE INSERT ON interventions FOR EACH ROW EXECUTE FUNCTION guard_interventions_g3();


CREATE OR REPLACE FUNCTION guard_call_capacity() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  PERFORM 1 FROM store_meta WHERE key = 'call_capacity_per_day' FOR UPDATE;
  IF (SELECT action_type FROM action_plan WHERE action_id = NEW.action_id) = 'phone_call' AND (SELECT COUNT(*) FROM interventions i JOIN action_plan a USING (action_id) WHERE a.action_type = 'phone_call' AND i.as_of = NEW.as_of) >= (SELECT CAST(value AS INTEGER) FROM store_meta WHERE key = 'call_capacity_per_day') THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Daily call capacity reached'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_call_capacity BEFORE INSERT ON interventions FOR EACH ROW EXECUTE FUNCTION guard_call_capacity();


CREATE OR REPLACE FUNCTION guard_responses() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF NOT EXISTS (SELECT 1 FROM interventions i JOIN action_plan a USING (action_id) WHERE i.action_id = NEW.action_id AND a.booking_id = NEW.booking_id AND i.as_of <= NEW.response_at) THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'A response needs an executed contact of this booking on or before it'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_responses BEFORE INSERT ON guest_responses FOR EACH ROW EXECUTE FUNCTION guard_responses();


CREATE OR REPLACE FUNCTION guard_closures_executed() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  PERFORM 1 FROM action_plan WHERE action_id = NEW.action_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM interventions WHERE action_id = NEW.action_id) THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'An executed action cannot be closed'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_closures_executed BEFORE INSERT ON action_closures FOR EACH ROW EXECUTE FUNCTION guard_closures_executed();


CREATE OR REPLACE FUNCTION guard_interventions_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Intervention log is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_interventions_append_only BEFORE UPDATE OR DELETE ON interventions FOR EACH ROW EXECUTE FUNCTION guard_interventions_append_only();


CREATE OR REPLACE FUNCTION guard_responses_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Response log is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_responses_append_only BEFORE UPDATE OR DELETE ON guest_responses FOR EACH ROW EXECUTE FUNCTION guard_responses_append_only();


CREATE OR REPLACE FUNCTION guard_closures_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Closure log is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_closures_append_only BEFORE UPDATE OR DELETE ON action_closures FOR EACH ROW EXECUTE FUNCTION guard_closures_append_only();


CREATE OR REPLACE FUNCTION guard_response_events_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Response event order is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_response_events_append_only BEFORE UPDATE OR DELETE ON response_events FOR EACH ROW EXECUTE FUNCTION guard_response_events_append_only();


CREATE OR REPLACE FUNCTION guard_plan_reviews_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Plan review log is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_plan_reviews_append_only BEFORE UPDATE OR DELETE ON plan_reviews FOR EACH ROW EXECUTE FUNCTION guard_plan_reviews_append_only();


CREATE OR REPLACE FUNCTION guard_attempts_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Execution attempt log is append-only'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_attempts_append_only BEFORE UPDATE OR DELETE ON execution_attempts FOR EACH ROW EXECUTE FUNCTION guard_attempts_append_only();


CREATE OR REPLACE FUNCTION guard_rejected_plan() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF NEW.scheduled_at IS NOT NULL AND EXISTS (SELECT 1 FROM plan_reviews WHERE booking_id = NEW.booking_id AND decision = 'rejected') THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Blocked: the G1 plan of this booking was rejected at review'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_rejected_plan BEFORE INSERT ON action_plan FOR EACH ROW EXECUTE FUNCTION guard_rejected_plan();


CREATE OR REPLACE FUNCTION guard_approval_transition() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF OLD.approval_status <> 'pending' OR NEW.approval_status NOT IN ('approved','rejected') OR NEW.needs_approval <> OLD.needs_approval THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Approval decision is final (only pending -> approved/rejected)'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_approval_transition BEFORE UPDATE OF approval_status, approved_by, approved_at, needs_approval ON action_plan FOR EACH ROW EXECUTE FUNCTION guard_approval_transition();


CREATE OR REPLACE FUNCTION guard_action_identity() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
  
  IF TRUE THEN RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Action identity is immutable'; END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER guard_action_identity BEFORE UPDATE OF booking_id, stay_date, room_type, action_type, rule_id, source_run_id, decision_at, known_from, scheduled_at, arrival_date, message_no, note, basis_event_id, created_at ON action_plan FOR EACH ROW EXECUTE FUNCTION guard_action_identity();


CREATE INDEX IF NOT EXISTS ix_action_booking ON action_plan (booking_id);
CREATE INDEX IF NOT EXISTS ix_action_cell ON action_plan (stay_date, room_type);
CREATE INDEX IF NOT EXISTS ix_interventions_as_of ON interventions (as_of);
CREATE INDEX IF NOT EXISTS ix_responses_booking ON guest_responses (booking_id);
CREATE INDEX IF NOT EXISTS ix_responses_action ON guest_responses (action_id);
CREATE INDEX IF NOT EXISTS ix_attempts_action ON execution_attempts (action_id);
